CREATE FUNCTION [dbo].[fnCalculateApplicableCladdingLevyCOW]
(
	@applicationId int
)
RETURNS varchar(4000)
AS
BEGIN

declare @bcaCow money;
declare @LandOwnershipTypeID int;
declare @ApplicableCladdingLevyCOW money;

--current applicable cost
select @ApplicableCladdingLevyCOW = ApplicableCladdingLevyCOW from Application where ApplicationID = @applicationId
if @ApplicableCladdingLevyCOW is null
		SET @ApplicableCladdingLevyCOW = 0.00;

SELECT @bcaCow = sum(CostOfWorks)
	from BCAClassification 
	where ApplicationID = @applicationId and CostOfWorks is not null
     and (
	 BCAClassificationContent like '2%' or
	 BCAClassificationContent like '3%' or
	 BCAClassificationContent like '4%' or
	 BCAClassificationContent like '5%' or
	 BCAClassificationContent like '6%' or
	 BCAClassificationContent like '7%' or
	  BCAClassificationContent like '8%'
	 );

	if @bcaCow is null
		SET @bcaCow = 0.00;
     
	 if(@ApplicableCladdingLevyCOW > @bcaCow)
	    SET @bcaCow = @ApplicableCladdingLevyCOW;
	 
	return @bcaCow;

END

