CREATE function [dbo].[fnGetBalanceFee]
(
	@applicationId int
)
returns money
as
begin
DECLARE @Balance money;	
DECLARE @TotalFee money;
DECLARE @TotalFeePaid money;

SELECT @TotalFee  =  SUM(F.TotalAmount) FROM Fee F WHERE F.ApplicationID = @applicationId

SELECT @TotalFeePaid  = SUM(F.TotalAmount) FROM Fee F WHERE F.ApplicationID  = @applicationId AND F.DateReceived IS NOT NULL

SELECT @Balance = @TotalFee - @TotalFeePaid
		
return  ISNULL(@Balance,0.0);
end

