CREATE FUNCTION [dbo].[fnGetContactDetails] 
(
	@applicantId int,
	@contactGroupName varchar(50)
)
RETURNS varchar(500)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @details varchar(500);
	DECLARE @salVal tinyint;
	DECLARE @title varchar(50);
	DECLARE @surname varchar(50);
	DECLARE @firstname varchar(50);
	DECLARE @company varchar(250);
	
	DECLARE @contactGroup int;
	
	select @contactGroup = cg.contactGroupid from 
	contactGroup cg, application a, applicationType at
	where lower(cg.ContactGroupName) = lower(@contactGroupName);
	
	SELECT top 1 @firstname = firstname,@title = title,@surname = lastname, @company = company 
	from ApplicationContact where applicationId = @applicantId and contactGroupId=@contactGroup;
	
	set @details = LTRIM(RTRIM(ISNULL(@title,'') +  ISNULL( ' ' + @firstname,'') + ISNULL(' ' + @surname,'') + ISNULL(' ' + @company,'')))
	
