-- =============================================
CREATE FUNCTION [dbo].[fngetCountersForPaymentReceivedNSW]
(	
	@ApplicationID INT,
	@CurrentStaffAccountID INT,
	@FromStateName VARCHAR(200),
	@TransitionName VARCHAR(200),
	@NextStateName VARCHAR(200),
	@FromStateCounterStatus VARCHAR(50),
	@NextStateCounterStatus VARCHAR(50),
	@CurrentCounterValue INT,
	@ResetCounterValue INT
)
RETURNS @CounterTable TABLE 
(	
	NewCounterValue INT,
	NewCounterStatus VARCHAR(200)
)
AS
BEGIN
	DECLARE @NewCounterValue INT
	DECLARE @NewCounterStatus VARCHAR(200)
	DECLARE @CurrentCounterState VARCHAR(200);

	SELECT TOP 1 @CurrentCounterState = ISNULL(NULLIF(CurrentCounterState,''),'off'),@NewCounterValue = Counter FROM Application WHERE ApplicationID = @ApplicationID

	-- IF CURRENT COUNTER STATUS IS ON KEEP IT ON
	IF(@CurrentCounterState ='off')
		BEGIN
			SET @NewCounterValue = @NewCounterValue
			SET @NewCounterStatus = 'off'
		END
	-- IF CURRENT COUNTER VALUE IS LESS THAN 28 DAYS PAUSE THE CLOCK
	ELSE
		BEGIN
			SET @NewCounterValue = @CurrentCounterValue
			SET @NewCounterStatus = 'on'
		END
	INSERT INTO @CounterTable VALUES (@NewCounterValue,@NewCounterStatus);
	RETURN
END

