-- =============================================
-- Author:		Roshan
-- Create date: 10-Nov-2020
-- Description:	Logic for deciding application counter value and counter status
-- =============================================
CREATE FUNCTION [dbo].[fngetNewToLodgeCounter]
(	
	@ApplicationID INT,
	@CurrentStaffAccountID INT,
	@FromStateName VARCHAR(200),
	@TransitionName VARCHAR(200),
	@NextStateName VARCHAR(200),
	@FromStateCounterStatus VARCHAR(50),
	@NextStateCounterStatus VARCHAR(50),
	@CurrentCounterValue INT,
	@ResetCounterValue INT
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT	
	CASE
		WHEN @CurrentCounterValue < 10 THEN 1
		WHEN @CurrentCounterValue > 10 AND @CurrentCounterValue < 20 THEN 2
		ELSE 3
	END AS NewCounterValue, 
	CASE
		WHEN @NextStateCounterStatus ='on' THEN 'off'
		WHEN @NextStateCounterStatus = 'off' THEN 'on'
		ELSE 'off'
	END AS NewCounterStatus	
)

