CREATE FUNCTION [dbo].[fnGetUnpaidFeesByFeeType]
(
	@ApplicationId int,
	@FeeType varchar(20),
	@compareOperator varchar(20)
)
RETURNS money
AS
BEGIN
	-- Declare the return variable here
	DECLARE @feeAmount money;
	set @feeAmount = 0;

	if(lower(@compareOperator) = 'like')
	begin
		DECLARE @FeeTypeLike varchar(25);
		SET @FeeTypeLike = '%' + @FeeType + '%';
		SELECT @feeAmount = sum(amount) from fee where applicationid = @ApplicationId 
		and lower(TRIM(FeeItem)) like lower(TRIM(@FeeTypeLike)) and DateReceived is null;
	end
	if(lower(@compareOperator) = 'equal')
	begin
		SELECT @feeAmount = sum(amount) from fee where applicationid = @ApplicationId 
		and lower(TRIM(FeeItem)) = TRIM(lower(@FeeType)) and DateReceived is null;
	end
	
	-- Return the result of the function
	RETURN @FeeAmount;

END

CREATE FUNCTION dbo.fnNormalizeInput (@InputString nvarchar(500))
RETURNS nvarchar(500)
WITH SCHEMABINDING
AS
BEGIN
    IF @InputString IS NULL RETURN NULL;

    DECLARE @OutputString nvarchar(500) = (@InputString);

    -- Characters to strip/normalize to spaces
    DECLARE @strip nvarchar(100) = N'''-–!""#$&()*.,/:;?@[\]_`{|}~´’“”+<=>•';
    DECLARE @repl  nvarchar(100) = REPLICATE(N' ', LEN(@strip));

    -- Map all listed chars to spaces
    SET @OutputString = TRANSLATE(@OutputString, @strip, @repl);

    -- Collapse multiple spaces to a single space
    WHILE CHARINDEX(N'  ', @OutputString) > 0
        SET @OutputString = REPLACE(@OutputString, N'  ', N' ');

    -- Trim ends
    RETURN LTRIM(RTRIM(@OutputString));
END

