 end else   
 begin  
  set @description = ISNULL(@rbsPermitNo,'') + ' was issued ' + CONVERT(VARCHAR(11),cast(@dateDecision as datetime),106)  + ' by ' + ISNULL(@Company,'')  + ' for '+ ISNULL(@ApplicationDescription,'') + CHAR(13) +   
  'A ' + ISNULL(@inspectionType,'') + ' Inspection was carried out '+ CONVERT(VARCHAR(11),cast(@inspectionDate as datetime),106) + ' and approved.'   
 end;  

 if( @decisionTypeId is not null and (@decisionTypeId = 3 or @decisionTypeId = 4))  
 begin  
    if(@decisionTypeId = 4)  
  begin  
   set @description = ISNULL(@description,'') + CHAR(13) + 'CFI Certificate No. ' + ISNULL(@certificationNumber,'') + ' was issued ' + CONVERT(VARCHAR(11),cast(@certificationDate as datetime),106) + CHAR(13);  
  end  
    else  
  begin  
   set @description = ISNULL(@description,'') + CHAR(13) + 'Occupancy Permit No. ' + ISNULL(@certificationNumber,'') + ' was issued ' + CONVERT(VARCHAR(11),cast(@certificationDate as datetime),106) + CHAR(13);  
  end  
 end   


 RETURN @description;  
END

CREATE FUNCTION [dbo].[fnPPARCounter]
(
	@applicationId int
)
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @counter int;
	Declare @IsCounterOn bit;
	Declare @AuditTrailCounter int;
	Declare @LatestAuditTrailChangeDate datetime;
	Declare @LatestAuditTrailCounter int;
	DECLARE @result int;

	SELECT @IsCounterOn = CounterStatus from application where applicationId = @applicationId;
	
	/*
		if(LatestAuditTrail exists)
		{
			If @IsCounterOn = 0, @counter = (Current Date) - LatestAuditTrail.ChangeDate + LatestAuditTrail.Counter
			else @counter = LatestAuditTrail.Counter
		}
		else
		{
			If @IsCounterOn = 0, @counter = (Current Date) - Application.DateCrated
			else @counter = 0
		}
		
		 if Counter = 0 return 0
         if Counter<= 60 return 2
         else return 1
	*/
	
	select @AuditTrailCounter = count(AuditTrailID) from AuditTrail where ApplicationID = @applicationId;
	if (@AuditTrailCounter > 0)
	begin
		select TOP 1 @LatestAuditTrailChangeDate = ChangeDate, @LatestAuditTrailCounter = Counter from AuditTrail where ApplicationID = @applicationId ORDER BY ChangeDate DESC;
		if (@IsCounterOn = 0)
		begin
			select @counter = DATEDIFF(day, @LatestAuditTrailChangeDate, GETDATE()) + @LatestAuditTrailCounter;
		end
		else
		begin
			select @counter = @LatestAuditTrailCounter;
		end
	end
	else
	begin
		if (@IsCounterOn = 0)
		begin
			select @counter = DATEDIFF(day, DateCreated, GETDATE()) from Application where ApplicationID = @applicationId;
		end
		else
		begin
			select @counter = 0;
		end
	end
	-- Return the result of the function

	select @result = 1;

	if (@counter = 0)
	begin
		select @result = 0;
	end
	else if (@counter <= 60)
	begin
		select @result = 2;
	end
	--RETURN @counter;
	RETURN @result;
END

