CREATE FUNCTION  [dbo].[fnPPARVicSmartTimeframe]
(
	@applicationId int
)
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @timeframe int;
	
	DECLARE @decisionDate datetime;
	set @decisionDate = null;
	select top 1 @decisionDate = dateDecision from decision where applicationId = @applicationId order by dateDecision;
	
	DECLARE @lodgedDate datetime;
	select @lodgedDate = dateCreated from application where applicationId = @applicationId;
	
	select @timeframe = (case when @decisionDate is null then 0 end);
	
	if (@timeframe = 0) 
	begin 
		RETURN @timeframe;
	end;
	else
	begin
		Declare @daysPassed int;
		set @daysPassed = dbo.GetWeekdays(@lodgedDate, DATEDIFF(day,@lodgedDate,@decisionDate));
		if (@daysPassed <= 10) 
			begin
				set @timeframe = 2;
			end;
		else
			begin
				set @timeframe = 1;
			end;
	end
	
		
	-- Return the result of the function
	RETURN @timeframe;

END

