CREATE FUNCTION [dbo].[spGetLatestDecisionForApplication]
(
	@applicationId int
)
RETURNS int
AS
BEGIN
	
	Declare @decisionId int;
	
	select top 1 @decisionId = decisionId from decision 
	where applicationId = @applicationId 
	order by dateDecision desc;
	
	-- Return the result of the function
	RETURN @decisionId;

END

CREATE FUNCTION [dbo].[spGetLatestRecommendationDateForApplication]
(
	@applicationId int,
	@meeting varchar(50)
)
RETURNS varchar(max)
AS
BEGIN
	
	Declare @meetingDate varchar(max);
	
	select top 1 @meetingDate = Convert(varchar(20),r.RecommendDate,103)+' - '+ISNULL(r.RecommendTime,'') from Recommendation r
	where r.applicationId = @applicationId and r.RecommendTo=@meeting
	and r.RecommendDate> GETDATE()
	order by r.DateOfRecommendation desc;



	
	-- Return the result of the function
	RETURN ISNULL(Convert(varchar(20),@meetingDate,103),'-');

END

CREATE FUNCTION [dbo].[spGetLatestRecommendationDecisionForApplication]
(
	@applicationId int
)
RETURNS varchar(max)
AS
BEGIN
	
	Declare @decisionId varchar(max);
	
	select top 1 @decisionId = DecisionDescription from RecommendationDecision rd
	join Recommendation r on rd.RecommendationDecisionID=r.RecommendationDecisionID
	where r.applicationId = @applicationId 
	order by r.DateOfRecommendation desc;
	
	-- Return the result of the function
	RETURN @decisionId;

END
